// Build-program conformance runner (`--build-vectors`, Phase B1 gate).
//
// Decodes build_vectors.json — the build-statement analog of expr_vectors.json.
// Each case carries a matcher record (captures + build_program IR), an env
// (slot values incl. $block-encoded blocks with real BOC bodies, well-known
// anchor/consumed, a lookup table) and the expected BuildOutcome, GENERATED by
// running the real Python BuildProgram.run (scratchpad generator; no
// hand-authored expectations). The C++ side executes the GENERATED build fns
// (gen_builds() table from `mch-codegen --builds build_vectors.json`) — a table
// generated from a different document is a hard error.
//
// $block encoding: {btype, opcode?, failed, broken, data:{...§12...},
// msg:{envelope fields}, tx:{transaction fields}, body_b64?} — the runner
// reconstructs a backing Message/Transaction/EventNode/Block so `.msg`
// accessors and `parse` (real MsgParse over the embedded BOC) behave exactly
// like production blocks.
#pragma once

#include <string>

namespace mch {

int run_build_vectors(const std::string &path);

}  // namespace mch
